#!/bin/sh
set -eu
umask 077
python3 -I -B - <<'INSTALL_CLOSURE_R29'
import base64,hashlib,os,platform,zlib
from pathlib import Path
assert os.geteuid()==0 and platform.system()=='Linux'
raw=zlib.decompress(base64.b64decode('',validate=True))
assert len(raw)==7921 and hashlib.sha256(raw).hexdigest()=='6280efc695edc808ae3836d2490aa16b93d38db68f64d2f9e2aeccbd04a4e69d'
p=Path('/root/t44-r9/close-window-r29-01.py');assert p.parent.resolve()==p.parent
fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o444)
with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
print('RESOURCE_CLOSURE_INSTALLED_NO_ACTION')
INSTALL_CLOSURE_R29
